// Engine-independent rules. Rendering and storage adapters belong outside this module.
import { REGIONS } from './level.js';

function normalizeRegions(regions) {
  if (!Array.isArray(regions) || regions.length === 0) {
    throw new TypeError('Game rules require at least one region.');
  }
  const keys = new Set();
  const stickerIds = new Set();
  return Object.freeze(Array.from(regions).map((region, index) => {
    if (!region || typeof region !== 'object' || Array.isArray(region)) {
      throw new TypeError(`Region ${index} must be an object.`);
    }
    const key = typeof region.key === 'string' ? region.key.trim() : '';
    const name = typeof region.name === 'string' ? region.name.trim() : '';
    if (!key || keys.has(key)) throw new TypeError(`Region ${index} needs a unique, nonempty key.`);
    if (!name) throw new TypeError(`Region ${key} needs a nonempty name.`);
    keys.add(key);

    const bounds = region.bounds;
    if (!bounds || ![bounds.x, bounds.y, bounds.w, bounds.h].every(Number.isFinite)
      || bounds.w <= 0 || bounds.h <= 0
      || !Number.isFinite(bounds.x + bounds.w) || !Number.isFinite(bounds.y + bounds.h)) {
      throw new TypeError(`Region ${key} needs finite bounds with positive width and height.`);
    }
    if (!Array.isArray(region.ids) || region.ids.length === 0) {
      throw new TypeError(`Region ${key} needs at least one sticker ID.`);
    }
    const ids = Array.from(region.ids).map(id => {
      if (typeof id !== 'string' || !id.trim() || stickerIds.has(id)) {
        throw new TypeError(`Region ${key} has an invalid or repeated sticker ID.`);
      }
      stickerIds.add(id);
      return id;
    });
    return Object.freeze({
      id: index,
      key,
      name,
      bounds: Object.freeze({ x: bounds.x, y: bounds.y, w: bounds.w, h: bounds.h }),
      ids: Object.freeze(ids),
    });
  }));
}

/** Each instance owns a validated copy of its regions and placement rules. */
export function createGameRules(regions) {
  const STAGES = normalizeRegions(regions);
  const ID_STAGE = new Map(STAGES.flatMap(stage => stage.ids.map(id => [id, stage.id])));
  const TOTAL = ID_STAGE.size;

  function emptyState() {
    return { version: 1, placedIds: [], stage: 0, completed: false };
  }

  /** Restore only legal region order; ignore unknown and duplicate sticker IDs. */
  function createGameState(saved) {
    if (typeof saved === 'string') {
      try {
        saved = JSON.parse(saved);
      } catch {
        return emptyState();
      }
    }
    if (!saved || typeof saved !== 'object' || !Array.isArray(saved.placedIds)) {
      return emptyState();
    }
    if (saved.version !== undefined && saved.version !== 1) return emptyState();

    const placedIds = [];
    const seen = new Set();
    let stage = 0;
    let stagePlaced = 0;

    for (const id of saved.placedIds) {
      if (!ID_STAGE.has(id) || seen.has(id)) continue;
      // A known future-region item makes the saved sequence invalid as a whole.
      if (ID_STAGE.get(id) !== stage) return emptyState();
      seen.add(id);
      placedIds.push(id);
      stagePlaced += 1;
      if (stagePlaced === STAGES[stage].ids.length) {
        stage += 1;
        stagePlaced = 0;
      }
    }

    const completed = placedIds.length === TOTAL;
    return { version: 1, placedIds, stage: Math.min(stage, STAGES.length - 1), completed };
  }

  /** Returns a fresh state even when the requested placement is rejected. */
  function placeSticker(state, id) {
    const next = createGameState(state);
    if (next.completed || next.placedIds.includes(id) || ID_STAGE.get(id) !== next.stage) {
      return next;
    }
    return createGameState({ version: 1, placedIds: [...next.placedIds, id] });
  }

  function undoLast(state) {
    const current = createGameState(state);
    return createGameState({ version: 1, placedIds: current.placedIds.slice(0, -1) });
  }

  function getProgress(state) {
    const current = createGameState(state);
    const stageIds = STAGES[current.stage].ids;
    const stagePlaced = stageIds.filter(id => current.placedIds.includes(id)).length;
    return {
      total: TOTAL,
      placed: current.placedIds.length,
      stagePlaced,
      stageTotal: stageIds.length,
      stageComplete: stagePlaced === stageIds.length,
      completed: current.completed,
    };
  }

  /** JSON string containing only version and ordered placement IDs. */
  function serializeState(state) {
    const current = createGameState(state);
    return JSON.stringify({ version: 1, placedIds: current.placedIds });
  }

  function resetState() {
    return emptyState();
  }

  return Object.freeze({
    STAGES, createGameState, placeSticker, undoLast, getProgress,
    isValidDrop, serializeState, resetState,
  });
}

/** Target dimensions may live on target.w/h or, as a fallback, item.w/h. */
export function isValidDrop(item, pointerWorld, toleranceWorld) {
  const target = item?.target;
  if (!target || !pointerWorld) return false;
  const width = target.w ?? item.w;
  const height = target.h ?? item.h;
  const values = [target.x, target.y, width, height, pointerWorld.x, pointerWorld.y, toleranceWorld];
  if (!values.every(Number.isFinite) || width <= 0 || height <= 0 || toleranceWorld < 0) {
    return false;
  }
  const centerX = target.x + width / 2;
  const centerY = target.y + height / 2;
  if (!Number.isFinite(centerX) || !Number.isFinite(centerY)) return false;
  return Math.hypot(pointerWorld.x - centerX, pointerWorld.y - centerY) <= toleranceWorld;
}

// Existing callers keep the same API; the default game uses the level's regions.
export const {
  STAGES, createGameState, placeSticker, undoLast,
  getProgress, serializeState, resetState,
} = createGameRules(REGIONS);

