"""Package this framework's named ES modules and native town sticker library.

Run --check for an in-memory preflight. The normal command creates the offline
HTML and source ZIP; wait until the game's source is stable before running it.
Use --html-only while documentation is still being finalized. Only Python's
standard library is required.
"""
from __future__ import annotations

import argparse
import base64
import hashlib
import json
import math
import mimetypes
import os
from pathlib import Path
import re
import shutil
import subprocess
import sys
import zipfile

IMPORT_RE = re.compile(
    r"(?m)^[ \t]*import\s*\{(?P<names>[^}]+)\}\s*from\s*"
    r"(?P<quote>['\"])(?P<path>[^'\"\n]+)(?P=quote)\s*;[ \t]*$"
)
ASSET_RE = re.compile(r"(?P<quote>['\"])(?P<path>\./assets/[^'\"\r\n]+\.png)(?P=quote)", re.I)
IDENTIFIER_RE = re.compile(r"^[A-Za-z_$][\w$]*$")
MODULE_PRIORITY = ("level.js", "logic.js", "camera.js", "sticker-fx.js", "paper-motion.js", "app.js")


def checked_path(base: Path, relative: str) -> Path:
    path = (base / relative.removeprefix("./")).resolve()
    if not path.is_relative_to(base.resolve()) or not path.is_file():
        raise ValueError(f"Missing or unsafe local file: {relative}")
    return path


def parse_level(source: str) -> dict:
    decoder = json.JSONDecoder()
    values = {}
    for name in ("LEVEL", "ITEMS", "REGIONS"):
        match = re.search(rf"\bexport\s+const\s+{name}\s*=\s*", source)
        if not match:
            raise ValueError(f"level.js does not declare {name}.")
        try:
            values[name], _ = decoder.raw_decode(source[match.end():])
        except json.JSONDecodeError as error:
            raise ValueError(f"{name} must use a JSON literal for this packager.") from error
    return values


def preflight_level(game: Path, values: dict) -> tuple[dict, list[Path]]:
    level, items, regions = (values[name] for name in ("LEVEL", "ITEMS", "REGIONS"))
    if not items or not regions:
        raise ValueError("The level must contain stickers and regions.")
    ids = [item["id"] for item in items]
    if len(ids) != len(set(ids)):
        raise ValueError("Game instance IDs must be unique.")
    region_ids = [id for region in regions for id in region["ids"]]
    if sorted(region_ids) != sorted(ids):
        raise ValueError("Every game instance must belong to exactly one region.")
    if len({region["key"] for region in regions}) != len(regions):
        raise ValueError("Region keys must be unique.")
    by_id = {item["id"]: item for item in items}
    for region in regions:
        bounds = region["bounds"]
        if not region["ids"] or not all(math.isfinite(bounds[k]) for k in ("x", "y", "w", "h")):
            raise ValueError(f"Invalid region: {region['key']}")
        if bounds["w"] <= 0 or bounds["h"] <= 0:
            raise ValueError(f"Invalid region dimensions: {region['key']}")
        for id in region["ids"]:
            target = by_id[id]["target"]
            if not all(math.isfinite(target[k]) for k in ("x", "y", "w", "h")) or target["w"] <= 0 or target["h"] <= 0:
                raise ValueError(f"Invalid target: {id}")
            if target["x"] < bounds["x"] - 1e-6 or target["y"] < bounds["y"] - 1e-6 or target["x"] + target["w"] > bounds["x"] + bounds["w"] + 1e-6 or target["y"] + target["h"] > bounds["y"] + bounds["h"] + 1e-6:
                raise ValueError(f"Target is outside its region: {id}")

    library = game / "assets" / "town"
    catalog = json.loads((library / "catalog.json").read_text(encoding="utf-8"))
    assets = catalog["assets"]
    if len(assets) != catalog["count"] or len({asset["id"] for asset in assets}) != len(assets):
        raise ValueError("The native sticker catalog count or IDs are invalid.")
    expected_library_count = level.get("sourceLibraryCount", catalog["count"])
    if len(assets) != expected_library_count:
        raise ValueError("The full native sticker library does not match LEVEL.sourceLibraryCount.")
    catalog_by_id = {asset["id"]: asset for asset in assets}
    sticker_paths = []
    for asset in assets:
        path = checked_path(library, asset["file"])
        if path.suffix.lower() != ".png" or not path.is_relative_to(library / "stickers"):
            raise ValueError(f"A library sticker must be a PNG under stickers/: {asset['id']}")
        expected_hash = asset.get("png_sha256")
        if expected_hash and hashlib.sha256(path.read_bytes()).hexdigest() != expected_hash:
            raise ValueError(f"Original PNG bytes have changed: {asset['id']}")
        sticker_paths.append(path)
    if len(set(sticker_paths)) != len(sticker_paths):
        raise ValueError("Catalog entries must reference different native PNG files.")
    checked_path(game, level["background"])
    for item in items:
        asset = catalog_by_id.get(item.get("assetId", item["id"]))
        if asset is None or item["image"] != "./assets/town/" + asset["file"]:
            raise ValueError(f"A game item must reference its original catalog PNG: {item['id']}")
        checked_path(game, item["image"])
    return catalog, sticker_paths


def named_bindings(text: str, separator: str = "as") -> list[tuple[str, str]]:
    result = []
    for part in text.split(","):
        part = part.strip()
        if not part:
            continue
        parts = re.split(rf"\s+{separator}\s+" if separator == "as" else r"\s*:\s*", part)
        if len(parts) > 2 or not all(IDENTIFIER_RE.fullmatch(value) for value in parts):
            raise ValueError(f"Unsupported named module binding: {part}")
        result.append((parts[0], parts[-1]))
    return result


def module_exports(source: str) -> tuple[dict[str, str], str]:
    exports = {}
    for match in re.finditer(r"(?m)^\s*export\s+(?:async\s+)?(?:function|class)\s+([A-Za-z_$][\w$]*)", source):
        exports[match[1]] = match[1]
    for match in re.finditer(r"(?m)^\s*export\s+(?:const|let|var)\s+([A-Za-z_$][\w$]*)", source):
        exports[match[1]] = match[1]
    for match in re.finditer(r"(?m)^\s*export\s+(?:const|let|var)\s*\{([^}]+)\}", source):
        for original, local in named_bindings(match[1], separator=":"):
            exports[local] = local

    def remove_export_list(match: re.Match) -> str:
        for local, exported in named_bindings(match[1]):
            exports[exported] = local
        return ""

    source = re.sub(r"(?m)^\s*export\s*\{([^}]+)\}\s*;", remove_export_list, source)
    source = re.sub(r"(?m)^([ \t]*)export\s+(?=(?:async\s+)?(?:function|class|const|let|var)\b)", r"\1", source)
    if re.search(r"(?m)^\s*export\b", source):
        raise ValueError("This packager supports named exports, not default exports or re-exports.")
    return exports, source


def inline_modules(game: Path) -> tuple[str, list[str], set[Path]]:
    sources, ordered, visiting = {}, [], set()
    embedded_paths = set()

    def visit(name: str) -> None:
        if name in ordered:
            return
        if name in visiting:
            raise ValueError(f"Circular module imports are unsupported: {name}")
        visiting.add(name)
        source = checked_path(game, name).read_text(encoding="utf-8")
        sources[name] = source
        matches = list(IMPORT_RE.finditer(source))
        remaining = IMPORT_RE.sub("", source)
        if re.search(r"(?m)^\s*import\b", remaining) or re.search(r"\bimport\s*\(", source) or "import.meta" in source:
            raise ValueError(f"Unsupported import syntax in {name}; use static named local imports.")
        for match in matches:
            path = match["path"]
            if not path.startswith("./"):
                raise ValueError(f"External module imports cannot be bundled: {path}")
            dependency = checked_path(game, str(Path(name).parent / path)).relative_to(game).as_posix()
            visit(dependency)
        visiting.remove(name)
        ordered.append(name)

    # level initializes the constants needed by logic; camera is part of the offline bundle.
    for name in MODULE_PRIORITY:
        visit(name)
    module_keys = {name: "./" + name for name in ordered}
    modules = ["'use strict';\nconst __modules = Object.create(null);"]
    for name in ordered:
        source = sources[name]

        def replace_import(match: re.Match) -> str:
            dependency = checked_path(game, str(Path(name).parent / match["path"])).relative_to(game).as_posix()
            pairs = named_bindings(match["names"])
            fields = ", ".join(original if original == local else f"{original}: {local}" for original, local in pairs)
            return f"const {{ {fields} }} = __modules[{json.dumps(module_keys[dependency])}];"

        source = IMPORT_RE.sub(replace_import, source)
        exports, source = module_exports(source)

        def embed_png(match: re.Match) -> str:
            path = checked_path(game, match["path"])
            embedded_paths.add(path)
            mime = mimetypes.guess_type(path.name)[0] or "image/png"
            uri = f"data:{mime};base64," + base64.b64encode(path.read_bytes()).decode("ascii")
            return json.dumps(uri)

        source = ASSET_RE.sub(embed_png, source)
        returned = ", ".join(f"{json.dumps(exported)}: {local}" for exported, local in exports.items())
        modules.append(f"__modules[{json.dumps(module_keys[name])}] = (() => {{\n{source}\nreturn {{ {returned} }};\n}})();")
    return "\n".join(modules), ordered, embedded_paths


def build_offline_html(game: Path) -> tuple[str, str, list[str], set[Path]]:
    html = (game / "index.html").read_text(encoding="utf-8")
    css = (game / "style.css").read_text(encoding="utf-8")
    script, order, embedded = inline_modules(game)
    if re.search(r"url\(\s*['\"]?(?!data:)(?:https?:|\./assets/)", css):
        raise ValueError("External CSS assets must be embedded before offline packaging.")
    style_tag = "<style>" + re.sub(r"</style", r"<\\/style", css, flags=re.I) + "</style>"
    html, count = re.subn(r"<link\b[^>]*\bhref=['\"]\./style\.css['\"][^>]*>", lambda _: style_tag, html, count=1)
    if count != 1:
        raise ValueError("index.html must reference ./style.css once.")
    safe_script = re.sub(r"</script", r"<\\/script", script, flags=re.I)
    script_tag = "<script>\n(() => {\n" + safe_script + "\n})();\n</script>"
    html, count = re.subn(r"<script\b[^>]*\bsrc=['\"]\./app\.js['\"][^>]*>\s*</script>", lambda _: script_tag, html, count=1)
    if count != 1:
        raise ValueError("index.html must reference ./app.js once.")
    if ASSET_RE.search(html) or re.search(r"<script\b[^>]*\bsrc=|<link\b[^>]*\brel=['\"]stylesheet", html):
        raise ValueError("Offline HTML still has external module, stylesheet or PNG references.")
    return html, script, order, embedded


def syntax_check(script: str, node: str | None) -> None:
    if not node:
        return
    result = subprocess.run([node, "--check", "--input-type=commonjs"], input="(() => {\n" + script + "\n})();", text=True, capture_output=True)
    if result.returncode:
        raise ValueError("Offline JavaScript failed syntax validation:\n" + result.stderr)


