def source_files(game: Path, sticker_paths: list[Path]) -> list[Path]:
    files = set(sticker_paths)
    library = game / "assets" / "town"
    for name in ("catalog.json", "catalog.csv", "README.txt", "README.md"):
        if (library / name).is_file():
            files.add(library / name)
    for directory in ("map", "reference", "sheets"):
        if (library / directory).is_dir():
            files.update(path for path in (library / directory).rglob("*") if path.is_file())
    for path in game.rglob("*"):
        parts = path.relative_to(game).parts
        if not path.is_file() or "assets" in parts or {"production-sources", "prompts", "atlas", "node_modules", ".git"}.intersection(parts):
            continue
        if path.suffix.lower() in {".js", ".css", ".html", ".md", ".txt", ".json"} or "docs" in path.relative_to(game).parts:
            files.add(path)
    return sorted(files)

